={{ (() => {
  const msg = $("Telegram Webhook").first().json.body.message
           || $("Telegram Webhook").first().json.body.edited_message
           || {};
  const text = (msg.text || msg.caption || '').trim();
  const chatId = String(msg.chat?.id || '');
  const messageId = String(msg.message_id || '');

  // Detect file type and extract file_id
  let fileArg = '';
  if (msg.voice) {
    fileArg = 'voice:' + msg.voice.file_id;
  } else if (msg.audio) {
    fileArg = 'voice:' + msg.audio.file_id;
  } else if (msg.document) {
    const mime = (msg.document.mime_type || '').toLowerCase();
    if (mime.startsWith('image/')) {
      fileArg = 'img:' + msg.document.file_id;
    } else {
      fileArg = 'doc:' + msg.document.file_id;
    }
  } else if (msg.photo && msg.photo.length > 0) {
    fileArg = 'img:' + msg.photo[msg.photo.length - 1].file_id;
  }

  // Detect location (static or live location update)
  if (msg.location) {
    fileArg = 'loc:' + msg.location.latitude + ',' + msg.location.longitude;
  }

  if (!text && !fileArg) return 'echo "No text or media received."';

  const safeText = text ? JSON.stringify(text) : "''";
  const safeFile = fileArg ? JSON.stringify(fileArg) : "''";
  const safeChatId = chatId ? JSON.stringify(chatId) : "''";
  const safeMsgId = messageId ? JSON.stringify(messageId) : "''";

  return '@MONET_HOME@/bridges/monet-tg.sh ' + safeText + ' ' + safeFile + ' ' + safeChatId + ' ' + safeMsgId;
})() }}

