const stdout = $input.item.json.stdout || '';
const msg = $('Telegram Webhook').first().json.body.message || $('Telegram Webhook').first().json.body.edited_message || {};
const chatId = String(msg.chat?.id || '');
const botToken = $env.BOT_TOKEN;

// Check for image markers [IMG]url[/IMG]
const imgMatch = stdout.match(/\[IMG\](https?:\/\/[^\[]+)\[\/IMG\]/);
let rawText = '';
let mediaUrl = '';

if (imgMatch) {
  mediaUrl = imgMatch[1].trim();
  rawText = stdout.replace(/\[IMG\]https?:\/\/[^\[]+\[\/IMG\]/, '').trim();
} else {
  rawText = stdout.trim();
}

// --- Markdown to Telegram HTML conversion ---
function mdToTgHtml(text) {
  let s = text;
  // Escape HTML entities first
  s = s.replace(/&/g, '&amp;');
  s = s.replace(/</g, '&lt;');
  s = s.replace(/>/g, '&gt;');

  // Code blocks (``` ... ```)
  s = s.replace(/```(?:\w+)?\n([\s\S]*?)```/g, '<pre>$1</pre>');

  // Inline code
  s = s.replace(/`([^`]+)`/g, '<code>$1</code>');

  // Bold (**text** or __text__)
  s = s.replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
  s = s.replace(/__(.+?)__/g, '<b>$1</b>');

  // Italic (*text* or _text_) - careful not to match inside words
  s = s.replace(/(?<![\w*])\*([^*]+?)\*(?![\w*])/g, '<i>$1</i>');
  s = s.replace(/(?<![\w_])_([^_]+?)_(?![\w_])/g, '<i>$1</i>');

  // Strikethrough
  s = s.replace(/~~(.+?)~~/g, '<s>$1</s>');

  // Links [text](url)
  s = s.replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, '<a href="$2">$1</a>');

  // Headings (# text) -> bold
  s = s.replace(/^#{1,6}\s+(.+)$/gm, '<b>$1</b>');

  // Bullet lists (- or * at start of line)
  s = s.replace(/^[\s]*[-*]\s+/gm, '\u2022 ');

  return s;
}

const htmlText = mdToTgHtml(rawText);

// --- Split at 4096 chars on paragraph/line/sentence boundaries ---
function splitMessage(text, limit) {
  if (text.length <= limit) return [text];
  const chunks = [];
  let remaining = text;
  while (remaining.length > limit) {
    let splitAt = remaining.lastIndexOf('\n\n', limit);
    if (splitAt < limit * 0.3) splitAt = remaining.lastIndexOf('\n', limit);
    if (splitAt < limit * 0.3) splitAt = remaining.lastIndexOf('. ', limit);
    if (splitAt < limit * 0.3) splitAt = limit;
    chunks.push(remaining.substring(0, splitAt + 1).trim());
    remaining = remaining.substring(splitAt + 1).trim();
  }
  if (remaining) chunks.push(remaining);
  return chunks;
}

const chunks = splitMessage(htmlText, 4096);

// Send overflow chunks (index 1+) directly via TG API
for (let i = 1; i < chunks.length; i++) {
  try {
    await new Promise(r => setTimeout(r, 300));
    await $helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + botToken + '/sendMessage',
      body: {
        chat_id: chatId,
        text: chunks[i],
        parse_mode: 'HTML'
      },
      headers: { 'Content-Type': 'application/json' },
      json: true
    });
  } catch (e) {
    // If HTML parse fails, retry without parse_mode
    try {
      await $helpers.httpRequest({
        method: 'POST',
        url: 'https://api.telegram.org/bot' + botToken + '/sendMessage',
        body: {
          chat_id: chatId,
          text: chunks[i]
        },
        headers: { 'Content-Type': 'application/json' },
        json: true
      });
    } catch (e2) { /* swallow */ }
  }
}

// Return first chunk for normal n8n flow — skip if empty (standalone handlers send directly)
const finalMsg = chunks[0] || '';
if (!finalMsg.trim()) return [];
return { json: { message: finalMsg, chatId, mediaUrl } };
